def priority(task, state, k=0.5, m=2.0, t=0.75, b=2.0):
    slack = max(0.0, task.due - task.estimated_runtime - state.now)
    tier = m if task.tenant == 'premium' else 1.0
    atc = tier * task.weight / max(task.estimated_runtime, 1e-6) * math.exp(-slack / (k * max(state.mean_est, 1e-6)))
    lateness = state.now + task.estimated_runtime - task.due
    if lateness > 0:
        atc *= 1.0 + b * lateness / max(task.estimated_runtime, 1e-6)
    if task.tenant == 'premium' and slack <= t * max(task.estimated_runtime, 1e-6):
        atc *= 1.0 + b
    return atc

def priority(task, state):
    # Critical ratio: time until due divided by estimated runtime
    remaining = task.due - state.now
    ratio = remaining / max(task.estimated_runtime, 1e-6)
    tenant_boost = 3.0 if task.tenant == 'premium' else 1.0
    return tenant_boost * task.weight * (1.0 / max(ratio, 1e-6))

def priority(task, state):
    # SLA tier risk: penalize tasks likely to miss their due date badly
    remaining = task.due - state.now
    est = max(task.estimated_runtime, 1e-6)
    if remaining <= 0:
        risk = 10.0
    elif remaining <= 0.25 * est:
        risk = 3.0
    elif remaining <= 1.0 * est:
        risk = 1.0
    else:
        risk = 0.0
    tenant_boost = 3.0 if task.tenant == 'premium' else 1.0
    return tenant_boost * (risk + task.weight) / est

