def priority(task, state, k=1.0, m=3.0, q_thresh=0.5, q_boost=2.0, eps=1e-6):
    # ATC with tenant tier, switching to stronger tenant preference when the
    # queue is congested (queue_work relative to capacity).
    slack = max(0.0, task.due - task.estimated_runtime - state.now)
    tier = m if task.tenant == 'premium' else 1.0
    load = state.queue_work / max(state.capacity, eps)
    if load > q_thresh:
        tier = (m * q_boost) if task.tenant == 'premium' else 1.0
    return tier * task.weight / max(task.estimated_runtime, eps) * math.exp(
        -slack / (k * max(state.mean_est, eps))
    )

def priority(task, state, k=1.0, m=3.0, late_mult=1.0, eps=1e-6):
    # ATC with tenant tier and a lateness-aware penalty: if the request is
    # already late, use a different urgency shape to prioritize clearing it.
    slack = max(0.0, task.due - task.estimated_runtime - state.now)
    tier = m if task.tenant == 'premium' else 1.0
    est = max(task.estimated_runtime, eps)
    if state.now > task.due:
        # Already late: prioritize by how far past due, amplified for premium.
        lateness = state.now - task.due
        return tier * late_mult * (1.0 + lateness / est) / est
    return tier * task.weight / est * math.exp(
        -slack / (k * max(state.mean_est, eps))
    )

def priority(task, state, k=1.0, m=3.0, guard_ratio=0.5, eps=1e-6):
    # Hybrid: ATC for normal requests, but switch to a slack-based guard
    # when remaining slack is below a fraction of estimated runtime,
    # ensuring tight-deadline jobs jump ahead.
    slack = max(0.0, task.due - task.estimated_runtime - state.now)
    tier = m if task.tenant == 'premium' else 1.0
    est = max(task.estimated_runtime, eps)
    if slack <= guard_ratio * est:
        # Tight deadline: prioritize by inverse slack, tier-weighted.
        return tier * (1.0 + (guard_ratio * est - slack) / est) / est
    return tier * task.weight / est * math.exp(
        -slack / (k * max(state.mean_est, eps))
    )

def priority(task, state, k=1.0, m=3.0, q_hi=1.0, q_lo=0.2, eps=1e-6):
    # ATC with load-adaptive tenant weighting: under low load, treat tenants
    # more equally to maximize throughput; under high load, sharply favor
    # premium to protect expensive SLA credits.
    est = max(task.estimated_runtime, eps)
    slack = max(0.0, task.due - est - state.now)
    load = state.queue_work / max(state.capacity, eps)
    if load >= q_hi:
        tier = m
    elif load <= q_lo:
        tier = 1.0
    else:
        frac = (load - q_lo) / max(q_hi - q_lo, eps)
        tier = 1.0 + (m - 1.0) * frac
    if task.tenant != 'premium':
        tier = 1.0
    return tier * task.weight / est * math.exp(-slack / (k * max(state.mean_est, eps)))

def priority(task, state, k=1.0, m=3.0, gamma=0.5, eps=1e-6):
    # ATC modified by task-type-aware scaling: variant calling and SV calling
    # often have larger downstream penalties, so give them a mild structural
    # boost relative to alignment, while retaining ATC's slack sensitivity.
    est = max(task.estimated_runtime, eps)
    slack = max(0.0, task.due - est - state.now)
    tier = m if task.tenant == 'premium' else 1.0
    if task.task_type == 'alignment':
        type_scale = 1.0
    elif task.task_type == 'variant_calling':
        type_scale = 1.0 + gamma
    else:
        type_scale = 1.0 + 2.0 * gamma
    return tier * type_scale * task.weight / est * math.exp(-slack / (k * max(state.mean_est, eps)))

