def priority(task, state, premium_boost=2.0, queue_pressure=0.1, type_weight=1.0):
    est = max(task.estimated_runtime, 1e-6)
    slack = task.due - state.now - est
    score = -slack / est
    if task.tenant == 'premium':
        score *= premium_boost
    score -= queue_pressure * (state.queue_work / max(state.capacity, 1e-6))
    if task.task_type == 'sv_calling':
        score *= (1.0 + 0.1 * type_weight)
    elif task.task_type == 'variant_calling':
        score *= (1.0 + 0.05 * type_weight)
    return score

