import math
def priority(task, state, type_weights=None):
    if type_weights is None:
        type_weights = {'alignment': 1.0, 'variant_calling': 1.2, 'sv_calling': 1.5}
    urgency = (task.due - state.now) / max(task.estimated_runtime, 1e-6)
    tenant_mult = 3.0 if task.tenant == 'premium' else 1.0
    return -urgency * tenant_mult * type_weights.get(task.task_type, 1.0)

import math
def priority(task, state, risk_scale=1.0, premium_mult=3.0):
    lateness_risk = (state.now + task.estimated_runtime - task.due) / max(task.estimated_runtime, 1e-6)
    if lateness_risk <= 0.25:
        band = 0.0
    elif lateness_risk <= 1.0:
        band = 1.0
    else:
        band = 2.0
    penalty = (1.0 if band == 0.0 else (3.0 if band == 1.0 else 10.0))
    if task.tenant == 'premium':
        penalty *= premium_mult
    density = task.resource_need / max(task.estimated_runtime, 1e-6)
    return -penalty * risk_scale + density

