def priority(task, state):
    # Due-date-slack ratio with dynamic queue congestion scaling
    est = max(task.estimated_runtime, 1e-6)
    slack = task.due - state.now
    tenant_mult = 3.0 if task.tenant == 'premium' else 1.0
