        lateness = -slack
        if lateness <= 0.25 * max(task.estimated_runtime, 1e-6):
            tier = 1.0
        elif lateness <= 1.0 * max(task.estimated_runtime, 1e-6):
            tier = 3.0
        else:
            tier = 10.0
    tenant = 3.0 if task.tenant == 'premium' else 1.0
    return -(task.due) - (tier * tenant * 1000.0) / max(task.estimated_runtime, 1e-6)
