def priority(task, state):
    # Penalty-risk density: expected penalty per core-second if delayed.
    # Approximate risk using tier weights and resource footprint.
    est = max(task.estimated_runtime, 1e-6)
    tenant = 3.0 if task.tenant == 'premium' else 1.0
    slack = task.due - state.now - est
    if slack >= 0:
        risk = 0.0
    else:
        lateness = -slack
        if lateness <= 0.25 * est:
            risk = 1.0
        elif lateness <= est:
            risk = 3.0
        else:
            risk = 10.0
    risk *= tenant
    # Higher risk density first; use due as tiebreaker.
    return risk / max(task.resource_need, 1e-6) - task.due * 1e-6
