    penalty_weight = 3.0 if task.tenant == 'premium' else 1.0
    score = GAMMA * lateness_class * penalty_weight
    score -= ALPHA * norm_est
    score -= BETA * (task.resource_need / max(state.capacity, 1e-6))
    if state.queue_len > 0:
        score += 0.1 / (1.0 + state.queue_work / max(state.capacity, 1e-6))
    return score

