def priority(task, state, k=1.0, m=3.0, eps=0.25):
    slack = task.due - task.estimated_runtime - state.now
    lateness_ratio = max(0.0, -slack) / max(task.estimated_runtime, 1e-6)
    tier = m if task.tenant == 'premium' else 1.0
    if lateness_ratio <= eps:
        urgency = tier / max(task.estimated_runtime, 1e-6)
    else:
        urgency = tier * (1.0 + lateness_ratio) / max(task.estimated_runtime, 1e-6)
    return urgency * math.exp(-max(0.0, slack) / (k * max(state.mean_est, 1e-6)))
```

