        return 1e9 + c * (task.weight / max(task.resource_need, 1e-6))
    premium_boost = 3.0 if task.tenant == 'premium' else 1.0
    return premium_boost * task.weight / (max(slack, 1e-6) + k * task.estimated_runtime)

def priority(task, state, w1=1.0, w2=0.5, w3=0.3, w4=0.2):
    import math
    slack = task.due - state.now - task.estimated_runtime
    premium_boost = 3.0 if task.tenant == 'premium' else 1.0
    type_boost = 1.0
    if task.task_type == 'variant_calling':
        type_boost = 1.2
    elif task.task_type == 'sv_calling':
        type_boost = 1.1
    queue_pressure = state.queue_work / max(state.capacity, 1e-6)
    return premium_boost * type_boost * (
        w1 * task.weight
        - w2 * task.estimated_runtime
        - w3 * task.resource_need
        - w4 * queue_pressure * slack
    ) / max(1.0 + w1 * task.weight, 1e-6)

def priority(task, state, urgency_pow=2.0, size_pow=0.5):
    import math
    slack = task.due - state.now - task.estimated_runtime
    premium_boost = 3.0 if task.tenant == 'premium' else 1.0
    if slack <= 0:
        return premium_boost * 1e6 / max(task.estimated_runtime, 1e-6)
    urgency = (1.0 / max(slack, 1e-6)) ** urgency_pow
    size_factor = 1.0 / (max(task.resource_need, 1e-6) ** size_pow)
    return premium_boost * task.weight * urgency * size_factor
